const en=document.body.dataset.lang==='en';
const dialog=document.querySelector('#detail-modal');
const body=document.querySelector('#modal-body');
let activePerson=null;
let trigger=null;
const showModal=(html,source)=>{trigger=source||document.activeElement;body.innerHTML=html;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';};
const closeModal=()=>{dialog.close();document.body.style.overflow='';trigger?.focus();};
dialog?.querySelector('.modal-close')?.addEventListener('click',closeModal);
dialog?.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
dialog?.addEventListener('close',()=>{document.body.style.overflow='';});
dialog?.addEventListener('cancel',()=>{document.body.style.overflow='';});
function launch(join=false){showModal(`<div class="launch-modal"><span class="eyebrow">${join?'BECOME A MATCHA':'YOUR NEXT HELLO'}</span><h2 id="modal-title">${join?(en?'Your next chapter,<br>with Matcha.':'成为某个人<br>最期待的 hello。'):(en?'A little closer<br>to something good.':'合拍的陪伴，<br>正在准备中。')}</h2><p>${join?(en?'Companion applications are not open yet. Recruitment requirements, service standards and application details will be published here before applications begin.':'陪陪招募尚未开放，申请入口将在本页公布。'):(en?'You’re exploring a product preview. Booking, registration, payments and messaging are not live. For now, meet the concept and explore the illustrative profiles.':'预约尚未开放。先选你喜欢的陪陪。')}</p><button class="button primary" data-close>${en?'Keep exploring':'继续认识 Matcha'} <span>↗</span></button></div>`);}
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>launch(b.dataset.action==='join')));
body?.addEventListener('click',event=>{if(event.target.closest('[data-close]'))closeModal();});
const toast=document.querySelector('#toast');let toastTimer;
function notify(text){toast.className='toast show';toast.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4000);}
function filter(type){document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b.dataset.filter===type);b.setAttribute('aria-pressed',b.dataset.filter===type?'true':'false');});let count=0;document.querySelectorAll('.companion-card').forEach(card=>{card.hidden=type!=='all'&&card.dataset.type!==type;if(!card.hidden)count++;});document.querySelectorAll('.catalog-row').forEach(row=>{row.hidden=![...row.querySelectorAll('.companion-card')].some(card=>!card.hidden);});const counter=document.querySelector('.filter-count');if(counter)counter.textContent=en?`${count} illustrative profile${count===1?'':'s'}`:`${count} 位示意陪陪`;}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>filter(b.dataset.filter)));
document.querySelectorAll('[data-service-filter]').forEach(a=>a.addEventListener('click',()=>filter(a.dataset.serviceFilter)));
let people;
async function profile(index,source){try{people??=await fetch('/companions.json').then(r=>{if(!r.ok)throw new Error('Profile unavailable');return r.json();});activePerson=index;const p=people[index];showModal(`<div class="profile-modal"><img class="modal-portrait" src="${p.image}" alt="${en?'Illustrative companion portrait':'陪陪示意肖像'} ${p.name}" width="560" height="640"><div class="modal-profile-body"><span class="eyebrow">MATCHA PP · ${en?'ILLUSTRATIVE PROFILE':'示意档案'}</span><h2 id="modal-title">${p.name}</h2><p>${en?p.en:p.zh}</p><div class="profile-tags">${(en?p.enTags:p.tags).map(t=>`<span>${t}</span>`).join('')}</div><div class="modal-tabs" role="tablist" aria-label="${en?'Companion service':'陪伴服务'}"><button class="modal-tab active" id="tab-about" role="tab" aria-selected="true" aria-controls="service-panel" tabindex="0" data-profile-tab="about">${en?'About':'关于我'}</button><button class="modal-tab" id="tab-skills" role="tab" aria-selected="false" aria-controls="service-panel" tabindex="-1" data-profile-tab="skills">${en?'Services':'陪伴服务'}</button></div><div id="service-panel" class="modal-service" role="tabpanel" aria-labelledby="tab-about"><h3>${en?'A little about me':'先认识一下'}</h3><p>${en?'A fictional profile showing how you could discover language, interests and companionship styles on Matcha. Take your time and find someone you feel comfortable with.':'选你的频道，聊你喜欢的。'}</p></div><div class="modal-privacy-note">${en?'Service duration, credits and boundaries should be clear before every booking.':'每一次下单前，先说清服务、时长、点数与相处边界。'}</div><div class="modal-actions"><button class="button primary" data-preview-book>${en?'About booking':'了解预约'} <span>↗</span></button><button class="button outline" data-preview-chat>${en?'Privacy details':'隐私说明'}</button></div><p class="modal-smallprint">${en?'AI-created portrait. Not a real bookable profile. No live availability, reviews or rates are implied.':'AI 示意档案 · 预约尚未开放。'}</p></div></div>`,source);}catch{notify(en?'Could not load this preview. Please try again.':'示意档案暂时无法载入，请稍后再试。');}}
document.querySelectorAll('[data-person]').forEach(b=>b.addEventListener('click',()=>profile(Number(b.dataset.person),b)));
body?.addEventListener('click',event=>{const tab=event.target.closest('[data-profile-tab]');if(tab){document.querySelectorAll('.modal-tab').forEach(b=>{b.classList.toggle('active',b===tab);b.setAttribute('aria-selected',b===tab?'true':'false');b.tabIndex=b===tab?0:-1;});const panel=document.querySelector('#service-panel');panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML=tab.dataset.profileTab==='skills'?`<h3>${en?'Choose how to connect':'选择你的陪伴方式'}</h3><p>${en?'Explore voice or video calls based on the companion’s actual services. This preview shows the structure; real rates and booking options are not published.':'按正式档案提供的项目，选择语音或视频通话。此预览展示服务结构；实际报价、语音样本与预约时间尚未公布。'}</p><a class="inline-link" href="/credits/">${en?'How credits work':'了解cha'} ↗</a>`:`<h3>${en?'A little about me':'先认识一下'}</h3><p>${en?'A fictional profile illustrating the Matcha companion discovery experience.':'这是虚构的示意档案，用来展示 Matcha 的语言、兴趣与服务选择体验。'}</p>`;}if(event.target.closest('[data-preview-book]'))launch();if(event.target.closest('[data-preview-chat]'))location.href='/privacy/';});
body?.addEventListener('keydown',event=>{if(!event.target.matches('.modal-tab'))return;if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...body.querySelectorAll('.modal-tab')];const selected=event.key==='Home'?tabs[0]:event.key==='End'?tabs.at(-1):tabs.find(t=>t!==event.target);selected.focus();selected.click();}});
const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#mobile-nav');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.hidden=!open;});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.hidden=true;toggle.setAttribute('aria-expanded','false');}));
const rate=document.querySelector('#credit-rate');const duration=document.querySelector('#credit-duration');
function calculate(){const value=Number(rate.value);const total=document.querySelector('#credit-total');total.textContent=rate.validity.valid&&Number.isFinite(value)?`${(value*Number(duration.value)/30).toLocaleString('zh-MY')} cha`:'请输入 1–10,000 的示例点数';}
if(rate){rate.addEventListener('input',calculate);duration.addEventListener('change',calculate);document.querySelector('#credit-calculator').addEventListener('submit',e=>e.preventDefault());calculate();}

const languagePicker=document.querySelector(".language-picker");document.addEventListener("click",e=>{if(languagePicker&&!languagePicker.contains(e.target))languagePicker.open=false;});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&languagePicker?.open){languagePicker.open=false;languagePicker.querySelector("summary").focus();}});
const motionControls=[...document.querySelectorAll('[data-motion-toggle]')];
function setMotionPaused(paused){document.body.classList.toggle('motion-paused',paused);motionControls.forEach(button=>{button.setAttribute('aria-pressed',String(paused));button.textContent=en?(paused?'Resume motion':'Pause motion'):(paused?'继续动效':'暂停动效');});}
motionControls.forEach(button=>button.addEventListener('click',()=>setMotionPaused(!document.body.classList.contains('motion-paused'))));
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)setMotionPaused(true);
document.querySelectorAll('[data-scroll-target]').forEach(button=>button.addEventListener('click',()=>{const track=document.getElementById(button.dataset.scrollTarget);track?.scrollBy({left:track.clientWidth*.85*Number(button.dataset.scrollDirection),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
document.querySelectorAll('[data-save-person]').forEach(button=>button.addEventListener('click',()=>{const saved=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(saved));notify(en?(saved?'Saved in this preview.':'Removed from this preview.'):(saved?'已加入本次浏览收藏。':'已取消收藏。'));}));
if('IntersectionObserver' in window){const motionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('motion-in-view',entry.isIntersecting)),{threshold:.08});document.querySelectorAll('.new-hero-showcase,.campaigns-section').forEach(element=>motionObserver.observe(element));}else{document.querySelectorAll('.new-hero-showcase,.campaigns-section').forEach(element=>element.classList.add('motion-in-view'));}
